export function icon(name, opts) {
  const { size = 18, cls = "" } = opts || {};
  const p = PATHS[name] || PATHS.circle;
  return `<svg class="${cls}" width="${size}" height="${size}" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true">${p}</svg>`;
}

